private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("graph and vertices must not be null");
    }
    int n = vertices.size();
    if (n <= 1) {
        return true; // empty or single vertex is trivially a clique
    }
    List<V> list = new ArrayList<>(vertices);
    for (int i = 0; i < n - 1; i++) {
        V vi = list.get(i);
        for (int j = i + 1; j < n; j++) {
            V vj = list.get(j);
            if (!graph.containsEdge(vi, vj) && !graph.containsEdge(vj, vi)) {
                return false;
            }
        }
    }
    return true;
}

