    if (table == null || pane == null) {
        return;
    }

    int rowCount = table.getRowCount();
    if (rowCount == 0) {
        return;
    }

    // Clamp the requested row index to a valid range
    if (row < 0) {
        row = 0;
    } else if (row >= rowCount) {
        row = rowCount - 1;
    }

    // 1. Select the specified row and clear any column selection
    table.setRowSelectionInterval(row, row);
    table.setColumnSelectionInterval(0, 0); // optional, ensures column selection stays minimal

    // 2. Scroll the table so that the selected row is visible
    Rectangle cellRect = table.getCellRect(row, 0, true);
    if (cellRect != null) {
        // Scroll within the viewport of the JScrollPane
        pane.getViewport().scrollRectToVisible(cellRect);
    }

    // 3. Delay repaint so the selection is rendered correctly
    SwingUtilities.invokeLater(() -> {
        // Schedule a second round to give the GUI time to finish layout and painting
        SwingUtilities.invokeLater(() -> table.repaint());
    });
}

