public final byte[] toByteArray() {
    // Assume we store individual byte arrays in an array called buffers.
    // If there are no buffers, return an empty byte array.
    if (buffers == null || buffers.length == 0) {
        return new byte[0];
    }

    // Compute the total length needed.
    int totalLength = 0;
    for (byte[] buf : buffers) {
        if (buf != null) {
            totalLength += buf.length;
        }
    }

    // If the total length is zero, return an empty array immediately.
    if (totalLength == 0) {
        return new byte[0];
    }

    // Allocate the result array and copy each buffer into it.
    byte[] result = new byte[totalLength];
    int offset = 0;
    for (byte[] buf : buffers) {
        if (buf != null && buf.length > 0) {
            System.arraycopy(buf, 0, result, offset, buf.length);
            offset += buf.length;
        }
    }

    return result;
}

