private void checkIfPackedField() throws IOException {
    // Packaged fields are stored as length‑delimited (wire type 2) scalar values.
    // If the current tag indicates such a wire type and the field is a
    // repeated scalar according to the descriptor, we treat the following
    // bytes as a packed block.  The state flag `readingPacked` is set and we
    // compute the position that marks the end of the packed data so that
    // subsequent reads stop correctly.
    if ((tag & 0x7) == 2) {                    // wire type == LENGTH_DELIMITED
        if (isPackedField(tag >>> 3)) {          // check descriptor for packedness
            readingPacked = true;
            int len = readRawVarint32();          // length of packed payload
            packedEnd = getPosition() + len;      // position where packed block ends
        } else {
            readingPacked = false;
        }
    } else {
        readingPacked = false;
    }
}

